/* UI requirements — local preview only. Server authorization is still required. */
const featureLabels={reference:'الجرد بمرجع',blind:'الجرد الأعمى',quick:'التعديل السريع',branding:'شعار الشركة',pdf:'تقارير PDF',word:'تقارير Word'};
function initUX(){db.branches??=[...new Set(db.ops.map(o=>o.branch))];db.companyProfile??={name:'شركة أوركيد',logo:null};db.planFeatures??=packages.map(()=>Object.fromEntries(Object.keys(featureLabels).map(k=>[k,true])));db.companyStates??={};for(const u of db.users)u.branches??=[...new Set(db.ops.filter(o=>o.supervisor===u.id||o.staff.includes(u.id)).map(o=>o.branch))]}
initUX();
function hasFeature(k){return db.planFeatures[db.plan]?.[k]===true}
function needFeature(k){if(!hasFeature(k)){toast('هذه الميزة غير متاحة في الباقة. راجع خيارات الترقية.');return false}return true}
function featureButton(k,label,action){return `<button ${hasFeature(k)?`onclick="${action}"`:'class="locked-feature" aria-disabled="true" onclick="go(\'plans\')"'}>${icon(hasFeature(k)?'check':'plans')}${label}${hasFeature(k)?'':' <span>ترقية الباقة</span>'}</button>`}
const uxLanding=landing;landing=function(){return uxLanding().replace('<section class="blue-workflow"',`<section class="blue-section comparison-section"><div class="blue-section-title"><span>الجرد، بخطوات أوضح</span><h2>قارن طريقة العمل.</h2><p>مقارنة بسير العمل الورقي اليدوي؛ المزامنة المشتركة تتطلب ربط الخادم.</p></div><div class="table-wrap"><table><thead><tr><th>خطوة العمل</th><th>RO</th><th>الطريقة الورقية التقليدية</th></tr></thead><tbody>${[['إدخال الكميات','باركود وكميات مباشرة','تدوين ونقل يدوي'],['الفروقات','مقارنة آلية مع المرجع','مراجعة وتجميع يدوي'],['التكرارات','تنبيه وقرار مراجعة موثق','تدقيق السجلات يدويًا'],['الفريق والفروع','إسناد العملية والمسؤول والموظفين','توزيع وتنسيق منفصل'],['التقارير','نتائج قابلة للتصدير حسب الباقة','إعداد التقرير بعد تجميع الأرقام'],['المزامنة اللحظية','ضمن خطة الربط بالخادم؛ غير مفعّلة حاليًا','تجميع النتائج بين الفرق']].map(row=>'<tr>'+row.map((c,i)=>`<${i?'td':'th'}>${c}</${i?'td':'th'}>`).join('')+'</tr>').join('')}</tbody></table></div></section><section class="blue-workflow"`)};
const uxCards=packageCards;packageCards=function(){let html=uxCards().replaceAll('<li>'+icon('scan')+' جرد مفتوح أو بمرجع</li>','<li>'+icon('scan')+' جرد حر دون مرجع</li>'),index=0;return html.replace(/<\/ul>/g,()=>`${Object.entries(featureLabels).map(([k,label])=>`<li class="${db.planFeatures[index]?.[k]?'':'locked-feature'}">${icon(db.planFeatures[index]?.[k]?'check':'plans')} ${label}${db.planFeatures[index]?.[k]?'':' · مقفلة'}</li>`).join('')}</ul>${++index?'':''}`)};
function branchOptions(names=db.branches,value=''){return names.map(b=>`<option value="${esc(b)}" ${b===value?'selected':''}>${esc(b)}</option>`).join('')}
function branchTools(){const names=canManage()?db.branches:(db.users.find(u=>u.id===activeUser())?.branches||[]);return `<section class="panel branch-panel"><div class="panel-title"><h2>الفروع وتوزيع العمليات</h2>${canManage()?'<button onclick="manageBranches()">إدارة الفروع</button>':''}</div><div class="branch-grid">${names.map(b=>`<article><h3>${esc(b)}</h3><strong>${visibleOps().filter(o=>o.branch===b).length}</strong><small>عمليات موزعة</small><p>${db.users.filter(u=>u.branches?.includes(b)).length} أعضاء بالفريق</p>${canManage()?`<button onclick="newOperationForBranch(this.dataset.branch)" data-branch="${esc(b)}">تخصيص عملية من الرصيد</button>`:''}</article>`).join('')||'<p>أضف أول فرع لتخصيص العمليات إليه.</p>'}</div><p class="muted">الرصيد مشترك بين الفروع. تُستهلك عملية عند إنشائها، ولا تُحتسب الفروع ضمن الباقة.</p></section>`}
function manageBranches(){if(!canManage())return;modal(`<h2>فروع الشركة</h2>${db.branches.map(b=>`<p>${esc(b)}</p>`).join('')}<label class="field">اسم الفرع الجديد<input name="branch" maxlength="80" required></label>${modalButtons('إضافة الفرع')}`,f=>{const b=f.get('branch').trim();if(!b||db.branches.includes(b))throw Error('أدخل اسم فرع جديد');db.branches.push(b);save('إضافة فرع '+b);closeDialog();render()})}
const uxDashboard=dashboard;dashboard=function(){return uxDashboard()+`<section class="panel"><div class="scan"><h2>أدوات الشركة</h2><div class="actions">${canManage()?featureButton('quick','قراءة باركود وتعديل الكمية',"openQuickEdit()")+`<button onclick="companyBranding()">اسم الشركة وشعار التقارير</button>`:''}</div></div></section>`+branchTools()};
let preferredBranch='';function newOperationForBranch(branch){preferredBranch=branch;newOperation()}
newOperation=function(){if(!canManage()||!requireOperationCredit())return;if(!db.branches.length){manageBranches();return}modal(`<h2>إنشاء عملية وتخصيصها لفرع</h2><p>سيُخصم رصيد عملية واحدة عند الإنشاء فقط.</p><label class="field">اسم العملية<input name="name" required maxlength="100"></label><label class="field">الفرع<select name="branch" onchange="refreshBranchTeam(this.value)">${branchOptions(db.branches,preferredBranch)}</select></label><label class="field">مسار الجرد<select name="type" onchange="document.getElementById('referenceFields').hidden=this.value!=='reference'"><option value="open">جرد حر — دون أصناف مسبقة</option>${hasFeature('reference')?'<option value="reference">جرد موجه — Excel أو CSV</option>':''}</select></label><div id="referenceFields" hidden><label class="field">قائمة الأصناف<input type="file" name="file" accept=".xlsx,.csv"></label><small>الأعمدة: barcode,name,qty أو الباركود، اسم الصنف، الكمية. في Excel اضبط عمود الباركود كنص لحفظ الأصفار.</small><button type="button" onclick="downloadTemplate()">قالب CSV</button>${hasFeature('blind')?'<label class="field"><span><input type="checkbox" name="blind" checked> جرد أعمى: إخفاء الكمية المرجعية عن الموظف</span></label>':'<p class="locked-feature">الجرد الأعمى مقفل في هذه الباقة.</p>'}</div><div id="branchTeam"></div><label class="field"><span><input type="checkbox" name="enabled" checked> السماح للفريق بالبدء فورًا</span></label>${modalButtons('إنشاء العملية')}`,async f=>{assertOperationCredit();const branch=f.get('branch'),supervisor=f.get('supervisor'),staff=f.getAll('staff'),type=f.get('type'),name=f.get('name').trim();if(!name||!db.branches.includes(branch))throw Error('تحقق من الاسم والفرع');const members=db.users.filter(u=>u.branches.includes(branch));if(!members.some(u=>u.id===supervisor&&u.role==='supervisor')||!staff.length||staff.some(id=>!members.some(u=>u.id===id&&u.role==='employee')))throw Error('اختر مسؤولًا وموظفين تابعين للفرع');let ref=[];if(type==='reference'){if(!needFeature('reference'))return;const file=f.get('file');if(!file?.size||file.size>5e6)throw Error('ارفع ملفًا لا يتجاوز 5 ميجابايت');const text=/\.xlsx$/i.test(file.name)?await ROFiles.xlsx(file):await file.text();ref=referenceWithArabic(text);if(!ref.length)throw Error('الملف فارغ')}if(type!=='open'&&type!=='reference')throw Error('نوع الجرد غير صحيح');assertOperationCredit();db.ops.unshift({id:'RO-'+newId().slice(0,8),name,branch,type,supervisor,staff,ref,blind:type==='reference'&&hasFeature('blind')&&f.has('blind'),enabled:f.has('enabled'),status:'open',date:new Date().toISOString().slice(0,10)});save('إنشاء عملية '+name+' للفرع '+branch);closeDialog();go('operations')});const select=$('#dialogForm').elements.branch;refreshBranchTeam(select.value);preferredBranch=''};
function refreshBranchTeam(branch){const members=db.users.filter(u=>u.branches.includes(branch));$('#branchTeam').innerHTML=`<label class="field">المسؤول<select name="supervisor" required>${members.filter(u=>u.role==='supervisor').map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><div class="field">موظفو الفرع<div class="checks">${members.filter(u=>u.role==='employee').map(u=>`<label><input type="checkbox" name="staff" value="${u.id}">${esc(u.name)}</label>`).join('')||'<p>أضف موظفي الفرع من فريق العمل أولًا.</p>'}</div></div>`}
function referenceWithArabic(text){const rows=csvParse(text.replace(/^\uFEFF/,''));if(!rows.length)throw Error('الملف فارغ');const map={'الباركود':'barcode','اسم الصنف':'name','الكمية':'qty'};rows[0]=rows[0].map(s=>map[s.trim()]||s.trim().toLowerCase());return reference(rows.map(r=>r.map(s=>safeCellForImport(s)).join(',')).join('\n'))}
function safeCellForImport(s){return '"'+String(s??'').replace(/"/g,'""')+'"'}
const uxVisible=visibleOps;visibleOps=function(){return uxVisible().filter(o=>db.role!=='employee'||o.enabled!==false)};
const uxDetail=detailPage;detailPage=function(){const o=op(selected);return uxDetail()+(o&&canManage()?`<section class="panel"><div class="scan"><h3>السماح بالجرد</h3><p>${o.enabled===false?'الفريق متوقف عن الإدخال؛ العملية تحتفظ برصيدها المستهلك.':'الفريق المسند يستطيع تسجيل الجرد.'}</p><button onclick="toggleCounting()">${o.enabled===false?'السماح ببدء الجرد':'إيقاف إدخال الفريق مؤقتًا'}</button></div></section>`:'')};
function toggleCounting(){if(!canManage())return;const o=op(selected);if(!o)return;o.enabled=o.enabled===false;save('تغيير السماح بالجرد '+o.id);render()}
const uxTeam=team;team=function(){const allowed=canManage()?db.branches:(db.users.find(u=>u.id===activeUser())?.branches||[]),members=db.users.filter(u=>u.branches.some(b=>allowed.includes(b)));return head('فريق الفرع والصلاحيات','المسؤول يدير أعضاء فروعه ضمن حد مستخدمي الشركة.',`<button onclick="newUser()">إضافة عضو</button>${canManage()?'<button onclick="manageBranches()">إضافة فرع</button>':''}`)+usageStrip()+`<div class="warning">إدارة محلية تجريبية؛ لا تُنشئ حسابات دخول فعلية.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الدور</th><th>الفروع</th><th>الإدخالات</th><th>الوحدات</th><th>التوزيع</th></tr></thead><tbody>${members.map(u=>`<tr><td>${esc(u.name)}</td><td>${roles[u.role]}</td><td>${u.branches.map(esc).join('، ')}</td><td>${logs().filter(l=>l.user===u.id&&visibleOps().some(o=>o.id===l.op)).length}</td><td>${logs().filter(l=>l.user===u.id&&visibleOps().some(o=>o.id===l.op)).reduce((s,l)=>s+l.qty,0)}</td><td>${canManage()?`<button onclick="assignUserBranches('${u.id}')">تعديل الفروع</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`+branchTools()};
newUser=function(){if(!canReview()||!requireUserSlot())return;const branches=canManage()?db.branches:(db.users.find(u=>u.id===activeUser())?.branches||[]);modal(`<h2>إضافة عضو للفريق</h2><label class="field">الاسم<input name="name" required maxlength="80"></label><label class="field">الدور<select name="role"><option value="employee">موظف جرد</option>${canManage()?'<option value="supervisor">المسؤول عن الفرع</option>':''}</select></label><label class="field">الفرع<select name="branch" required>${branchOptions(branches)}</select></label>${modalButtons('إضافة العضو')}`,f=>{assertUserSlot();const name=f.get('name').trim(),role=f.get('role'),branch=f.get('branch');if(!name||!branches.includes(branch)||!['employee','supervisor'].includes(role)||(!canManage()&&role!=='employee'))throw Error('تحقق من بيانات العضو');db.users.push({id:newId(),name,role,branches:[branch]});save('إضافة عضو '+name);closeDialog();render()})};
function assignUserBranches(id){if(!canManage())return;const u=db.users.find(u=>u.id===id);if(!u)return;modal(`<h2>فروع ${esc(u.name)}</h2><p>تبقى العمليات السابقة مسندة حتى إغلاقها.</p>${db.branches.map(b=>`<label class="field"><span><input type="checkbox" name="branch" value="${esc(b)}" ${u.branches.includes(b)?'checked':''}>${esc(b)}</span></label>`).join('')}${modalButtons('حفظ التوزيع')}`,f=>{const names=f.getAll('branch');if(!names.length||names.some(b=>!db.branches.includes(b)))throw Error('اختر فرعًا صحيحًا');u.branches=names;save('توزيع فروع '+u.name);closeDialog();render()})}
let quickEditMode=false;
function openQuickEdit(){if(!canManage()||!needFeature('quick'))return;if(!visibleOps().some(o=>o.status==='open'))return toast('أنشئ عملية مفتوحة أولًا');quickEditMode=true;go('scan')}
const uxScan=scanPage;scanPage=function(){return (db.role==='employee'?`<div class="employee-welcome"><b>مرحبًا ${esc(user(activeUser()))}</b><p>﴿وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ﴾</p><small>سورة الإسراء · الآية 35</small></div>`:'')+(quickEditMode&&canManage()?'<div class="warning">التعديل الإداري: امسح الباركود ثم اختر الموقع لمراجعة الكمية قبل اعتمادها.</div>':'')+uxScan()};
function applyQuantityCorrection(operation,barcode,location,qty,reason){const o=op(operation);if(!o||o.status!=='open'||!visibleOps().includes(o)||!canReview()||!barcode||!location||!reason.trim()||!Number.isSafeInteger(qty)||qty<0||qty>1e9)throw Error('تحقق من العملية والصنف والموقع والكمية والسبب');const old=logs(operation).filter(l=>l.barcode===barcode&&l.location===location),before=old.map(l=>({id:l.id,qty:l.qty,user:l.user}));old.forEach(l=>l.excluded=true);const record={id:newId(),op:operation,barcode,location,qty,user:canManage()?'company':activeUser(),note:reason,time:new Date().toISOString(),excluded:false,source:'correction',replaces:before};db.logs.push(record);db.resolutions[[operation,barcode,location].join('|')]={actor:canManage()?'حساب الشركة':user(activeUser()),time:record.time,decision:'تعديل الكمية إلى '+qty,record:record.id};save('تصحيح كمية '+barcode+' في '+location+' من '+before.reduce((s,l)=>s+l.qty,0)+' إلى '+qty+'؛ السبب: '+reason);return record}
function correctionCard(barcode,location='A1'){const o=op(selected);if(!o||o.status!=='open'||!canReview()||!barcode.trim()||!location.trim())return;const ref=o.ref.find(r=>r.barcode===barcode),count=logs(o.id).filter(l=>l.barcode===barcode&&l.location===location).reduce((s,l)=>s+l.qty,0);modal(`<h2>اعتماد كمية الصنف</h2><div class="item-preview"><strong>${esc(ref?.name||'صنف غير موجود في المرجع')}</strong><p dir="ltr">${esc(barcode)}</p><p>${esc(o.name)} · ${esc(location)}</p><p>المعدود الحالي في الموقع: <b>${count}</b></p></div><label class="field">الكمية المعتمدة<input name="qty" type="number" min="0" max="1000000000" step="1" value="${count}" required></label><label class="field">سبب التصحيح<input name="reason" maxlength="500" required></label><p>يحفظ النظام الإدخالات السابقة مستبعدة للمراجعة، ولا يمسح أثرها.</p>${modalButtons('اعتماد الكمية')}`,f=>{if(canManage()&&!needFeature('quick'))return;applyQuantityCorrection(o.id,barcode,location,Number(f.get('qty')),f.get('reason').trim());closeDialog();render();toast('تم اعتماد الكمية مع حفظ الأثر السابق')})}
const uxAttach=attachScan;attachScan=function(){uxAttach();const form=$('#scanForm');if(!form)return;const original=form.onsubmit;form.onsubmit=e=>{const o=op(form.elements.operation.value);if(o?.enabled===false){e.preventDefault();return toast('حساب الشركة أوقف إدخال هذه العملية')}if(quickEditMode&&canManage()){e.preventDefault();if(!needFeature('quick'))return;selected=form.elements.operation.value;const barcode=form.elements.barcode.value.trim(),location=form.elements.location.value.trim();if(!barcode||!location)return toast('امسح الباركود وحدد الموقع أولًا');return correctionCard(barcode,location)}return original(e)};if(quickEditMode&&canManage()){$('.save-count').innerHTML=icon('review')+' مراجعة الصنف وتعديل الكمية';form.elements.qty.closest('label').hidden=true;$('.quantity-shortcuts').hidden=true;$('.shortcut-note').hidden=true;form.elements.employee.closest('label').hidden=true;startCamera()}form.addEventListener('ro:barcode',()=>{if(quickEditMode&&canManage()&&!$('#dialog').open){selected=form.elements.operation.value;correctionCard(form.elements.barcode.value.trim(),form.elements.location.value.trim())}});const barcode=form.elements.barcode;if(db.role==='employee'&&op(selected)?.type==='reference'&&!op(selected).blind){const card=document.createElement('p');card.className='item-preview';barcode.closest('label').after(card);const update=()=>{const r=op(selected).ref.find(r=>r.barcode===barcode.value.trim());card.textContent=r?r.name+' · الكمية المرجعية: '+r.qty:'الباركود غير موجود في المرجع'};barcode.addEventListener('input',update);const timer=setInterval(()=>{if(!document.contains(card))return clearInterval(timer);update()},700)}};
const uxGo=go;go=function(p){if(p!=='scan')quickEditMode=false;return uxGo(p)};
const uxReview=reviewPage;reviewPage=function(){let html=uxReview();let i=0;return html.replace(/<div class="review-card">/g,()=>{const n=i++;return `<div class="review-card"><button class="correction-action" onclick="reviewCorrection(${n})">تعديل الكمية</button>`})};
function reviewCorrection(i){const entry=groups()[i];if(!entry||!canReview())return;const l=entry[1][0];selected=l.op;correctionCard(l.barcode,l.location)}
const uxAddon=requestAddon;requestAddon=function(quantity){uxAddon(quantity);const form=$('#dialogForm'),handler=form.onsubmit;form.querySelector('.modal-actions').insertAdjacentHTML('beforebegin',`<label class="field">الفرع المخصص للإضافة<select name="targetBranch" required>${branchOptions()}</select></label><small>تظل الإضافة قيد المراجعة؛ اختيار الفرع لا ينشئ عملية ولا يستهلك رصيدًا.</small>`);form.onsubmit=async e=>{const branch=form.elements.targetBranch.value;if(!db.branches.includes(branch)){e.preventDefault();return toast('اختر الفرع')}const old=new Set(db.addonRequests.map(r=>r.id));await handler(e);const r=db.addonRequests.find(r=>!old.has(r.id));if(r){r.branch=branch;save()}}};
const uxAddons=addonsPage;addonsPage=function(){return uxAddons()+`<section class="panel"><div class="scan"><h3>تخصيص الإضافات المعتمدة</h3>${db.addonRequests.filter(r=>r.status==='approved'&&r.branch).map(r=>`<p>${esc(r.branch)} · ${r.quantity} عمليات مطلوبة <button data-branch="${esc(r.branch)}" onclick="newOperationForBranch(this.dataset.branch)">إنشاء عملية للفرع من الرصيد المتاح</button></p>`).join('')||'<p>لا توجد إضافات معتمدة مرتبطة بفرع.</p>'}<small>الرصيد مشترك؛ هذا الاختصار يحدد الفرع ويطبق حد الرصيد قبل الإنشاء.</small></div></section>`};
function companyBranding(){if(!canManage())return;modal(`<h2>هوية الشركة والتقارير</h2><label class="field">اسم الشركة<input name="name" value="${esc(db.companyProfile.name)}" maxlength="100" required></label>${hasFeature('branding')?'<label class="field">الشعار PNG أو JPEG<input type="file" name="logo" accept="image/png,image/jpeg"></label><small>الحد 500 كيلوبايت. لا تُقبل ملفات SVG.</small><label><input type="checkbox" name="removeLogo"> حذف الشعار الحالي</label>':'<p class="locked-feature">رفع الشعار يحتاج ترقية الباقة.</p>'}${modalButtons('حفظ الهوية')}`,async f=>{const name=f.get('name').trim();if(!name)throw Error('أدخل اسم الشركة');let logo=db.companyProfile.logo;const file=f.get('logo');if(file?.size){if(!needFeature('branding'))return;if(file.size>500000||!['image/png','image/jpeg'].includes(file.type))throw Error('اختر PNG أو JPEG بحد 500 كيلوبايت');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('تعذر قراءة الصورة'));r.readAsDataURL(file)});const image=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(Error('الصورة غير صالحة'));im.src=data});logo={data,type:file.type,ratio:image.naturalWidth/image.naturalHeight};if(!Number.isFinite(logo.ratio)||logo.ratio<0.2||logo.ratio>10)throw Error('اختر شعارًا بنسبة أبعاد مناسبة')}if(f.has('removeLogo'))logo=null;db.companyProfile={name,logo};save('تحديث هوية الشركة');closeDialog();render()})}
reports=function(){const os=visibleOps();if(!os.some(o=>o.id===selected))selected=os[0]?.id;return head('تقارير الجرد','نتائج العملية والفروقات بهوية شركتك.',`<button onclick="exportReport('csv')">CSV</button>${featureButton('pdf','PDF',"printReport()")}${featureButton('word','Word',"wordReport()")}${canManage()?'<button onclick="companyBranding()">هوية التقرير</button>':''}`)+`<section class="panel"><div class="toolbar"><select aria-label="اختر عملية التقرير" onchange="selected=this.value;render()">${os.map(o=>`<option value="${o.id}" ${o.id===selected?'selected':''}>${esc(o.name)} · ${esc(o.branch)}</option>`).join('')}</select></div><div id="reportDocument" class="report-document">${reportHeading()}${selected?resultsTable(selected):'<p>لا توجد عملية متاحة.</p>'}</div></section><p class="muted">PDF عبر نافذة الطباعة في المتصفح. Word ملف DOCX قابل للتحرير. النتائج محلية في هذه النسخة.</p>`};
function reportHeading(){return `<div class="report-brand">${hasFeature('branding')&&db.companyProfile.logo?`<img alt="شعار الشركة" src="${db.companyProfile.logo.data}">`:''}<div><h2>${esc(db.companyProfile.name)}</h2><p>تقرير ${esc(op(selected)?.name||'الجرد')} · ${esc(op(selected)?.branch||'')}</p><small>نسخة محلية تجريبية · ${new Date().toLocaleDateString('ar-SA')}</small></div></div>`}
function printReport(){if(canReview()&&needFeature('pdf')&&op(selected))window.print()}
function wordReport(){if(!canReview()||!needFeature('word')||!op(selected))return;const blob=ROFiles.docx(db.companyProfile.name,op(selected),results(selected),hasFeature('branding')?db.companyProfile.logo:null),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=selected+'.docx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const uxLimits=platformLimits;platformLimits=function(){return uxLimits()+`<section class="panel"><div class="scan"><h2>مزايا كل باقة</h2><p>المزايا قابلة للتعديل دون تغيير الكود. التحكم محلي للمعاينة.</p><div class="feature-matrix">${packages.map((p,i)=>`<article><h3>${p.name}</h3><button onclick="editPackage(${i})">تعديل الاسم والسعر والمدة</button>${Object.entries(featureLabels).map(([k,label])=>`<label class="feature-toggle">${label}<input type="checkbox" role="switch" ${db.planFeatures[i][k]?'checked':''} onchange="setPlanFeature(${i},'${k}',this.checked)"></label>`).join('')}</article>`).join('')}</div></div></section>`};
function setPlanFeature(i,k,value){if(db.platformRole!=='superadmin'||!packages[i]||!(k in featureLabels))return;db.planFeatures[i][k]=!!value;save('تعديل ميزة '+featureLabels[k]+' للباقة '+packages[i].name)}
function editPackage(i){if(db.platformRole!=='superadmin')return;const p=packages[i];modal(`<h2>تعديل الباقة</h2><label class="field">الاسم<input name="name" value="${esc(p.name)}" maxlength="60" required></label><label class="field">السعر بالريال<input name="price" type="number" min="0" max="1000000" step="1" value="${p.price}" required></label><label class="field">المدة بالأيام<input name="days" type="number" min="1" max="3650" value="${p.days}" required></label>${modalButtons('حفظ الباقة')}`,f=>{const name=f.get('name').trim(),price=Number(f.get('price')),days=Number(f.get('days'));if(!name||!Number.isSafeInteger(price)||price<0||price>1e6||!Number.isSafeInteger(days)||days<1||days>3650)throw Error('تحقق من القيم');Object.assign(p,{name,price,days});db.packageDetails=packages.map(({name,price,days})=>({name,price,days}));save('تحديث بيانات الباقة');closeDialog();render()})}
if(db.packageDetails)db.packageDetails.slice(0,4).forEach((p,i)=>Object.assign(packages[i],p));
function companyDirectory(){if(db.platformRole!=='superadmin')return '';return `<section class="panel"><div class="panel-title"><h2>الشركات المسجلة على هذا المتصفح</h2></div><div class="table-wrap"><table><thead><tr><th>الشركة</th><th>البريد</th><th>الحالة</th><th>إجراء الإدارة</th></tr></thead><tbody>${db.demoAccounts.map(a=>{const request=db.requests.find(r=>r.accountId===a.id||r.email===a.email),status=db.companyStates[a.id]||'pending';return `<tr><td>${esc(a.company)}</td><td>${esc(a.email)}</td><td>${{pending:'قيد الاعتماد',active:'نشط تجريبيًا',suspended:'معلق'}[status]}</td><td><button onclick="setCompanyState('${a.id}','${status==='active'?'suspended':'active'}')">${status==='active'?'تعليق الشركة':'اعتماد الشركة تجريبيًا'}</button>${request?`<button onclick="reviewRequest('${request.id}')">طلب الاشتراك</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">سجّل حسابًا تجريبيًا ليظهر هنا.</td></tr>'}</tbody></table></div><p class="muted">الاعتماد هنا حالة محلية، ولا ينشئ بيئة شركة أو يفعل اشتراكًا سحابيًا.</p></section>`}
function setCompanyState(id,status){if(db.platformRole!=='superadmin'||!db.demoAccounts.some(a=>a.id===id)||!['active','suspended'].includes(status))return;db.companyStates[id]=status;save('تغيير حالة شركة '+id+' إلى '+status);render()}
const uxOverview=platformOverview;platformOverview=function(){return uxOverview()+companyDirectory()};
const uxRender=render;render=function(){initUX();uxRender();if(db.role==='supervisor'&&page==='dashboard')$('#app').insertAdjacentHTML('afterbegin',`<div class="warning">متابعة محلية للعمليات المسندة لفروعك · ${visibleOps().length} عمليات · لا توجد مزامنة بين الأجهزة بعد.</div>`);if(!document.body.classList.contains('public-flow')){const company=document.querySelector('.company>div');if(company)company.innerHTML=esc(db.companyProfile.name)+'<small>مساحة عمل تجريبية</small>'}if(db.role==='employee'&&page==='scan'){const status=$('#cameraStatus');if(status&&!cameraStream)status.textContent='تبدأ الكاميرا تلقائيًا بعد إذنك. إن منعها المتصفح استخدم زر فتح الكاميرا.'}};
render();
